    t = nearest(resources, self_pos)
    if t is not None:
        return step_toward(self_pos, t)

    # Fallbacks: contest center or track opponent.
    center = (gw // 2, gh // 2) if gw and gh else opp_pos
    if env == "resource_collection_denial":
        return step_away(self_pos, opp_pos)
